<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$error='';$user=null;
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){
  csrf();
  if(($_POST['action']??'')==='logout'){$_SESSION=[];session_regenerate_id(true);header('Location: /');exit;}
  $slot=(string)($_POST['slot']??'');$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');
  if(!in_array($slot,['raul','adrian'],true)||strlen($email)>254||strlen($password)>1024)throw new RuntimeException('login');
  $logs=VestiaLogCapture::db();$now=time();$ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'');$account=hash('sha256',$slot.':'.$email);
  $logs->exec('BEGIN IMMEDIATE');
  try {
   $logs->prepare('DELETE FROM login_attempts WHERE attempted_at<?')->execute([$now-900]);
   $s=$logs->prepare('SELECT COUNT(*) FROM login_attempts WHERE bucket=?');$s->execute(['ip:'.$ip]);$ipCount=(int)$s->fetchColumn();$s->execute(['account:'.$account]);$accountCount=(int)$s->fetchColumn();
   $limited=$ipCount>=30||$accountCount>=10;
   if(!$limited){$s=$logs->prepare('INSERT INTO login_attempts VALUES(?,?)');$s->execute(['ip:'.$ip,$now]);$s->execute(['account:'.$account,$now]);}
   $logs->exec('COMMIT');
  }catch(Throwable $e){$logs->exec('ROLLBACK');throw $e;}
  if($limited){http_response_code(429);$error='Demasiados intentos. Espera 15 minutos antes de volver a entrar.';}
  else{
   $s=slot_db($slot)->prepare('SELECT id,name,password_hash FROM users WHERE email=?');$s->execute([$email]);$accountRow=$s->fetch();
   $valid=password_verify($password,$accountRow['password_hash']??'$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.');
   if(!$accountRow||!$valid){usleep(250000);$error='No hemos podido entrar. Comprueba el entorno, el correo y la contraseña.';}
   else{session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(24));$_SESSION['auth']=['slot'=>$slot,'id'=>(int)$accountRow['id'],'at'=>$now,'stamp'=>hash('sha256',$accountRow['password_hash'])];header('Location: /');exit;}
  }
 }
 $user=identity();
}catch(Throwable $e){$error='No se ha podido acceder. Comprueba los datos o inténtalo en unos minutos.';}
